const L = (ko: string, uz: string, en: string, ru: string) => ({
  ko,
  uz,
  en,
  ru,
});

type S5U2I18nText = {
  ko: string;
  uz: string;
  en: string;
  ru: string;
};

type S5U2I18nOptions = {
  ko: string[];
  uz: string[];
  en: string[];
  ru: string[];
};

const S5U2_NATIVE_DISTRACTORS: S5U2I18nOptions = {
  ko: ['really', 'usually', 'maybe', 'again'],
  uz: ['haqiqatan', 'odatda', 'balki', 'yana'],
  en: ['really', 'usually', 'maybe', 'again'],
  ru: ['действительно', 'обычно', 'возможно', 'снова'],
};

const normalizeS5U2BuilderAnswer = (value: string) =>
  value
    .replace(/[.!?,]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

const normalizeS5U2BuilderTranslations = (
  value?: Partial<S5U2I18nText>,
): S5U2I18nText => {
  const en = normalizeS5U2BuilderAnswer(value?.en || value?.ko || '');

  return {
    // 한국어 UI에서 한국어 정답 칩이 그대로 노출되지 않게 영어 의미 사용
    ko: en,
    uz: normalizeS5U2BuilderAnswer(value?.uz || en),
    en,
    ru: normalizeS5U2BuilderAnswer(value?.ru || en),
  };
};

const shuffledS5U2BuilderOptions = (
  answer: string,
  distractors: string[],
): string[] => {
  const chunks = normalizeS5U2BuilderAnswer(answer).split(' ').filter(Boolean);

  const extras = distractors
    .filter((item) => !chunks.includes(item))
    .slice(0, chunks.length >= 6 ? 3 : 2);

  const options = [...chunks, ...extras];

  if (options.length <= 2) {
    return options.reverse();
  }

  return [...options.slice(2), ...options.slice(0, 2)];
};

const localizedS5U2BuilderOptions = (
  answer: S5U2I18nText,
): S5U2I18nOptions => ({
  ko: shuffledS5U2BuilderOptions(answer.ko, S5U2_NATIVE_DISTRACTORS.ko),
  uz: shuffledS5U2BuilderOptions(answer.uz, S5U2_NATIVE_DISTRACTORS.uz),
  en: shuffledS5U2BuilderOptions(answer.en, S5U2_NATIVE_DISTRACTORS.en),
  ru: shuffledS5U2BuilderOptions(answer.ru, S5U2_NATIVE_DISTRACTORS.ru),
});

const withS5U2SentenceBuilders = (
  questions: Record<string, Record<string, any>>,
) =>
  Object.fromEntries(
    Object.entries(questions).map(([id, question]) => {
      if (question.type !== 'sentence_builder') {
        return [id, question];
      }

      const answerI18n = normalizeS5U2BuilderTranslations(
        question.answerTranslation,
      );

      return [
        id,
        {
          ...question,
          instruction: L(
            '한국어를 듣고 뜻을 알맞은 순서로 배열하세요.',
            'Koreyscha gapni tinglab, ma’nosini to‘g‘ri tartibda tuzing.',
            'Listen to the Korean sentence and arrange its meaning.',
            'Прослушайте корейское предложение и соберите его перевод.',
          ),
          audioText: question.audioText || question.answer,
          answerI18n,
          optionsI18n: localizedS5U2BuilderOptions(answerI18n),
        },
      ];
    }),
  );

